import React, { useState } from 'react';
import './App.css';
import Dashboard from './components/Dashboard';
import ImageUpload from './components/ImageUpload';
import RiskPrediction from './components/RiskPrediction';
import AlertPanel from './components/AlertPanel';

/**
 * ============================================
 * AquaGuard AI - Main Application
 * ============================================
 * Waterborne Disease Monitoring Dashboard
 * 
 * Tabs:
 * 1. Dashboard - Overview with stats and charts
 * 2. Image Detection - Upload images for YOLO analysis
 * 3. Risk Prediction - ML-based outbreak prediction
 * 4. Alerts - Alert history and management
 */
function App() {
  const [activeTab, setActiveTab] = useState('dashboard');

  const tabs = [
    { id: 'dashboard', label: '📊 Dashboard', icon: '📊' },
    { id: 'detection', label: '🔬 Image Detection', icon: '🔬' },
    { id: 'prediction', label: '🧠 Risk Prediction', icon: '🧠' },
    { id: 'alerts', label: '🚨 Alerts', icon: '🚨' },
  ];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard onNavigate={setActiveTab} />;
      case 'detection':
        return <ImageUpload />;
      case 'prediction':
        return <RiskPrediction />;
      case 'alerts':
        return <AlertPanel />;
      default:
        return <Dashboard onNavigate={setActiveTab} />;
    }
  };

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="header__logo">
          <div className="header__icon">🌊</div>
          <div>
            <div className="header__title">AquaGuard AI</div>
            <div className="header__subtitle">Waterborne Disease Monitoring</div>
          </div>
        </div>
        <nav className="header__nav">
          {tabs.map(tab => (
            <button
              key={tab.id}
              className={`header__nav-btn ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => setActiveTab(tab.id)}
              id={`nav-${tab.id}`}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </header>

      {/* Main Content */}
      <main className="main">
        <div className="fade-in" key={activeTab}>
          {renderContent()}
        </div>
      </main>

      {/* Footer */}
      <footer style={{
        textAlign: 'center',
        padding: '1.5rem',
        color: 'var(--text-muted)',
        fontSize: '0.8rem',
        borderTop: '1px solid var(--border-color)',
      }}>
        AquaGuard AI v1.0 — AI-Based Waterborne Disease Monitoring & Outbreak Prediction System
      </footer>
    </div>
  );
}

export default App;
